{
  "implementation": "def solve(case):
    passing = case["passing"]
    failing = case["failing"]
    required = set(case["required_difference"])
    unresolved = set(case["unresolved_difference"])

    diff = []
    for item in failing:
        if item not in passing:
            diff.append(item)

    tests = 0

    def test(subset):
        if any(x in unresolved for x in subset):
            return "UNRESOLVED"
        if required.issubset(set(subset)):
            return "FAIL"
        else:
            return "PASS"

    def ddmin(cs):
        nonlocal tests
        if len(cs) == 0:
            return []
        n = len(cs)
        if n == 1:
            tests += 1
            if test(cs) == "FAIL":
                return cs
            else:
                return []
        p = 2
        while p <= n:
            part_size = n // p
            remainder = n % p
            subsets = []
            start = 0
            for i in range(p):
                size = part_size + (1 if i < remainder else 0)
                subsets.append(cs[start:start+size])
                start += size
            for subset in subsets:
                tests += 1
                outcome = test(subset)
                if outcome == "FAIL":
                    return ddmin(subset)
            start = 0
            for i in range(p):
                size = len(subsets[i])
                complement = cs[:start] + cs[start+size:]
                tests += 1
                outcome = test(complement)
                if outcome == "FAIL":
                    return ddmin(complement)
                start += size
            p *= 2
        return cs

    isolated = ddmin(diff)
    return {"isolated_difference": isolated, "tests": tests}
